#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/printk.h>
#include <string.h>

#define TEST_BUF_SIZE 128

ZTEST_SUITE(heap_corruption_suite, NULL, NULL, NULL, NULL, NULL);

ZTEST(heap_corruption_suite, test_read)
{
    printk("START - test_read\n");
    char *buf = k_malloc(TEST_BUF_SIZE);
    zassert_not_null(buf, "Failed to allocate buf");
    memset(buf, 'A', TEST_BUF_SIZE);

    /* Simulate a read operation */
    printk("test_read: Using buf\n");
    /* ... some operations with buf ... */

    k_free(buf); /* Correctly free the buffer once. */

    printk("END - test_read\n");
}
